<template>
 <NetworkWidgetDialog :title="t('安装 FastNet 插件','Install FastNet')" @close="$emit('close')">
  <div class="fastnet-install" data-fastnet-install-dialog>
   <div class="fastnet-install-product">
    <span class="fastnet-install-icon"><HomeGlyph name="activity"/></span>
    <div><strong>FastNet</strong><p>{{t('外网速率 · NAT · IPv6','Internet speed · NAT · IPv6')}}</p></div>
    <span class="fastnet-install-badge">{{badge}}</span>
   </div>
   <p class="fastnet-install-description" role="status">{{description}}</p>
   <div v-if="error" class="fastnet-install-error" role="alert"><span aria-hidden="true">!</span><p>{{error}}</p></div>
   <div v-else class="fastnet-install-note"><HomeGlyph :name="busy?'clock':'check'"/><p>{{busy?t('可以关闭此窗口，安装会在后台继续。','You can close this window. Installation continues in the background.'):t('安装后再选择卡片位置，不会自动开始测速。','Choose a card position after installation. No speed test starts automatically.')}}</p></div>
   <div class="fastnet-install-footer">
    <div class="fastnet-install-links"><a href="/cgi-bin/luci/admin/store" target="_blank" rel="noopener">{{t('软件中心','Software center')}}<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M9 3h4v4M13 3 6 10M7 3H3v10h10V9"/></svg></a><button v-if="!installing" type="button" @click="$emit('recheck')" :disabled="state==='checking'" data-recheck-card-install>{{t('重新读取','Reload status')}}</button></div>
    <div class="fastnet-install-actions"><button type="button" class="fastnet-install-back" @click="$emit('close')">{{t('返回','Back')}}</button><button v-if="state!=='unknown'" type="button" class="fastnet-install-primary" :disabled="installing||state==='checking'" :aria-busy="busy||state==='checking'" @click="$emit('install')" data-confirm-card-install><span v-if="busy||state==='checking'" class="fastnet-install-spinner" aria-hidden="true"/>{{action}}</button></div>
   </div>
  </div>
 </NetworkWidgetDialog>
</template>
<script setup lang="ts">
import {computed} from 'vue'
import NetworkWidgetDialog from '../NetworkWidgetDialog.vue'
import HomeGlyph from '../HomeGlyph.vue'
import type {CardInstallState} from './installContext'
const props=defineProps<{state:'checking'|CardInstallState;installing:boolean;error:string}>()
defineEmits<{(event:'close'):void;(event:'install'):void;(event:'recheck'):void}>()
const english=window.vue_lang==='en',t=(zh:string,en:string)=>english?en:zh
const busy=computed(()=>props.installing||props.state==='installing')
const badge=computed(()=>busy.value?t('正在安装','Installing'):props.state==='checking'?t('检查中','Checking'):props.state==='update_required'?t('需要更新','Update needed'):props.state==='unknown'?t('待确认','Unconfirmed'):props.state==='failed'?t('安装未完成','Incomplete'):t('尚未安装','Not installed'))
const description=computed(()=>busy.value?t('正在安装 FastNet，完成后即可添加外网测速卡片。','Installing FastNet. You can add the Internet speed card once it is ready.'):props.state==='checking'?t('正在确认插件和安装状态，请稍候。','Checking the plugin and installation status.'):props.state==='update_required'?t('当前插件版本尚未提供可用卡片，请先升级或修复 FastNet。','Update or repair FastNet to make this card available.'):props.state==='unknown'?t('暂时无法确认安装状态，请重新读取或到软件中心检查。','Reload the installation status or check FastNet in the software center.'):props.state==='failed'?t('FastNet 安装未完成，请检查软件源后重试。','FastNet installation did not complete. Check the package source and retry.'):t('添加外网测速模块前，需要先安装 FastNet 插件。','Install FastNet before adding the Internet speed module.'))
const action=computed(()=>props.installing?t('正在安装','Installing'):props.state==='checking'?t('正在检查','Checking'):props.state==='installing'?t('查看安装进度','View progress'):props.state==='update_required'?t('升级或修复','Update or repair'):props.state==='failed'?t('重试安装','Retry installation'):t('安装插件','Install plugin'))
</script>
