tnet-install-links :is(a,button):hover{color:var(--qs-card-accent)}.fastnet-install-links svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}.fastnet-install-actions{display:flex;gap:8px;flex:none}.fastnet-install-actions button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:8px 16px;border:1px solid var(--qs-card-line);border-radius:8px;background:var(--qs-card-panel);color:var(--qs-card-text);font:inherit;font-size:13px;font-weight:500;white-space:nowrap;cursor:pointer}.fastnet-install-actions .fastnet-install-primary{background:var(--qs-card-accent);border-color:var(--qs-card-accent);color:var(--qs-card-panel)}.fastnet-install-actions button:hover{filter:brightness(.96)}.fastnet-install button:disabled{opacity:.6;cursor:default}.fastnet-install-spinner{width:13px;height:13px;flex:none;border:1.5px solid currentColor;border-right-color:transparent;border-radius:50%;animation:fastnet-install-spin .8s linear infinite}@keyframes fastnet-install-spin{to{transform:rotate(360deg)}}@media(max-width:540px){.fastnet-install-footer{align-items:stretch;flex-direction:column;gap:14px;margin-top:20px}.fastnet-install-links{justify-content:space-between}.fastnet-install-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.fastnet-install-actions>button:only-child{grid-column:1/-1}.fastnet-install-actions button{padding:8px 10px;white-space:normal;text-align:center}.fastnet-install-product{gap:10px}.fastnet-install-icon{width:42px;height:42px}.fastnet-install-badge{font-size:10px;padding:3px 6px}.fastnet-install-product p{font-size:11px}}@media(pointer:coarse){.fastnet-install-actions button,.fastnet-install-links a,.fastnet-install-links button{min-height:44px}}@media(prefers-reduced-motion:reduce){.fastnet-install-spinner{animation:none}}
